import React, { useState } from 'react';
import { Container, Button, Input, InputGroup, InputGroupText } from 'reactstrap';

const ChatRoom = ({ chatId, otherUserId, loginUserId, goBack }) => {
    const [message, setMessage] = useState('');
    const [messages, setMessages] = useState([]);

    const handleSend = () => {
        if (message.trim() !== '') {
            const newMessage = {
                id: Date.now(),
                sender: loginUserId,
                text: message.trim(),
            };
            setMessages([...messages, newMessage]);
            setMessage('');
        }
    };

    return (
        <Container style={{ position: 'relative', height: '100%' }}>
            <Button style={{ fontSize: '10px' }} color="secondary" onClick={goBack}>
                뒤로가기
            </Button>
            <p>
                채팅방 ID: {chatId}, 상대방 ID: {otherUserId}, 내 ID: {loginUserId}
            </p>
            <div
                style={{
                    margin: '20px 0',
                    border: '1px solid #ccc',
                    padding: '10px',
                    height: 'calc(100% - 120px)',
                    overflowY: 'scroll',
                    display: 'flex',
                    flexDirection: 'column-reverse',
                }}
            >
                {messages.map((msg) => (
                    <div
                        key={msg.id}
                        style={{
                            marginBottom: '10px',
                            display: 'flex',
                            justifyContent: msg.sender === loginUserId ? 'flex-end' : 'flex-start',
                        }}
                    >
                        <div
                            style={{
                                maxWidth: '60%',
                                padding: '10px',
                                borderRadius: '10px',
                                background: msg.sender === loginUserId ? '#007bff' : '#f1f0f0',
                                color: msg.sender === loginUserId ? '#fff' : '#000',
                                wordWrap: 'break-word',
                            }}
                        >
                            <strong>{msg.sender}</strong>: {msg.text}
                        </div>
                    </div>
                ))}
            </div>
            <div style={{ position: 'absolute', bottom: '0', left: '0', width: '100%' }}>
                <InputGroup>
                    <Input
                        type="text"
                        value={message}
                        onChange={(e) => setMessage(e.target.value)}
                        placeholder="메시지를 입력하세요"
                    />
                    <InputGroupText>
                        <Button color="primary" onClick={handleSend}>
                            전송
                        </Button>
                    </InputGroupText>
                </InputGroup>
            </div>
        </Container>
    );
};

export default ChatRoom;
